UI_HTML = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<style>\n:root{color-scheme:light dark;font-family:ui-sans-serif,system-ui,-apple-system,sans-serif}\nbody{margin:0;padding:22px;background:transparent;color:inherit}\nmain{max-width:760px;margin:auto}\nheader{display:flex;align-items:center;gap:12px;margin-bottom:18px}\n.logo{width:42px;height:42px;border-radius:13px;background:linear-gradient(135deg,#7257ff,#22b8a8);display:grid;place-items:center;color:white;font-weight:900;font-size:20px}\nh1{font-size:20px;margin:0}p{opacity:.75;margin:5px 0 0}\n.panel{border:1px solid color-mix(in srgb,currentColor 18%,transparent);border-radius:16px;padding:18px;margin-top:14px}\n.status{display:inline-flex;align-items:center;gap:7px;font-size:13px;padding:7px 10px;border-radius:99px;background:color-mix(in srgb,#22a06b 15%,transparent)}\n.dot{width:8px;height:8px;border-radius:50%;background:#22a06b}\nh2{font-size:15px;margin:0 0 12px}\n.steps{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}\n.step{padding:12px;border-radius:12px;background:color-mix(in srgb,currentColor 6%,transparent);font-size:13px}\n.step b{display:block;margin-bottom:5px}\npre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px;max-height:320px;overflow:auto;background:color-mix(in srgb,currentColor 7%,transparent);padding:12px;border-radius:10px}\n.muted{font-size:12px;opacity:.65}\n@media(max-width:520px){body{padding:14px}.steps{grid-template-columns:1fr}}\n</style>\n</head>\n<body>\n<main>\n<header><div class=\"logo\">A</div><div><h1>AtDev VideoAI</h1><p>Open-source video creation workspace</p></div></header>\n<div class=\"status\"><span class=\"dot\"></span> Connected through your MCP server</div>\n<section class=\"panel\"><h2>What you can create</h2><div class=\"steps\">\n<div class=\"step\"><b>01 · Plan</b>Build scenes, titles, backgrounds and timing.</div>\n<div class=\"step\"><b>02 · Generate</b>Turn declarative JSON into an editable project.</div>\n<div class=\"step\"><b>03 · Render</b>Export motion-graphics videos to MP4 with FFmpeg.</div>\n</div></section>\n<section class=\"panel\"><h2>Latest tool result</h2><p id=\"message\">When AtDev VideoAI creates or lists a project, its result will appear here.</p><pre id=\"result\" hidden></pre></section>\n<p class=\"muted\">No credit system. Rendering uses FFmpeg. This tool creates motion graphics; it does not synthesize AI footage or voice.</p>\n</main>\n<script>\n(function(){\n const result=document.getElementById('result'),message=document.getElementById('message');\n function show(data){try{const payload=data?.params?.content||data?.params?.structuredContent||data?.params||data;result.textContent=JSON.stringify(payload,null,2);result.hidden=false;message.textContent='AtDev VideoAI returned a result.';}catch(e){}}\n window.addEventListener('message',event=>{const d=event.data;if(!d||typeof d!=='object')return;if(d.method==='ui/notifications/tool-result'||d.method==='ui/notifications/tool-input')show(d);});\n if(window.openai?.toolOutput)show(window.openai.toolOutput);\n})();\n</script>\n</body>\n</html>"
